// Define the required callback signature
typedef int (*ActionPtr)(int input);

// Concrete callback implementation
int AddFive(int x) { return x + 5; }

// Event system function (takes the callback)
int ProcessEvent(ActionPtr func, int data) {
    if (func == NULL) return -1;
    return func(data);
}

// Variable assignment (Implicit reference)
ActionPtr my_callback = AddFive;

// Direct function pointer assignment
int (*ptr_manual)(int) = &AddFive;

// Usage: Call through the system function
int result = ProcessEvent(my_callback, 10);

// Direct call using the pointer variable
int direct_res = ptr_manual(20);
